#!/bin/sh
set -eu
case "${1:-all}" in all|c23-a|c23-b|c23-c) ;; *) exit 2;; esac
if test "${1:-all}" = all || test "${1:-all}" = c23-a; then
echo INICIO_c23-a
kubectl get --raw=/readyz --request-timeout=20s
kubectl wait --for=condition=Ready node/cka-w1 --timeout=120s
test -z "$(kubectl get namespace p23a --ignore-not-found -o name)"
kubectl create namespace p23a
kubectl -n p23a wait --for=create serviceaccount/default --timeout=90s
printf '%s\n' '{"apiVersion":"v1","kind":"Pod","metadata":{"name":"web","namespace":"p23a","labels":{"app":"web"}},"spec":{"terminationGracePeriodSeconds":1,"containers":[{"name":"app","image":"busybox:1.37.0-musl","imagePullPolicy":"Never","command":["sh","-c","mkdir -p /www; printf '\''%s\\n'\'' '\''GATEWAY_OK'\'' >/www/index.html; exec httpd -f -p 8080 -h /www"]}]}}' | kubectl apply -f -
printf '%s\n' '{"apiVersion":"v1","kind":"Service","metadata":{"name":"web","namespace":"p23a"},"spec":{"selector":{"app":"web"},"ports":[{"port":80,"targetPort":8080}]}}' | kubectl apply -f -
kubectl -n p23a wait --for=condition=Ready pod/web --timeout=180s
printf '%s\n' '{"apiVersion":"gateway.networking.k8s.io/v1","kind":"Gateway","metadata":{"name":"entrada","namespace":"p23a"},"spec":{"gatewayClassName":"traefik","listeners":[{"name":"http","protocol":"HTTP","port":8000}]}}' | kubectl apply -f -
printf '%s\n' '{"apiVersion":"gateway.networking.k8s.io/v1","kind":"HTTPRoute","metadata":{"name":"web","namespace":"p23a"},"spec":{"parentRefs":[{"name":"entrada"}],"hostnames":["web.gateway.test"],"rules":[{"matches":[{"path":{"type":"PathPrefix","value":"/"}}],"backendRefs":[{"name":"web","port":80}]}]}}' | kubectl apply -f -
