deadline=$(($(date +%s)+120)); until (kubectl -n p23a get gateway entrada -o json | jq -e '.metadata.generation as $generation | .spec.gatewayClassName=="traefik" and any(.status.conditions[]?; .type=="Accepted" and .status=="True" and .observedGeneration==$generation) and any(.status.conditions[]?; .type=="Programmed" and .status=="True" and .observedGeneration==$generation)' && kubectl -n p23a get httproute web -o json | jq -e '.metadata.generation as $generation | (.spec.hostnames|index("web.gateway.test"))!=null and any(.status.parents[]?; .parentRef.name=="entrada" and (.parentRef.namespace==null or .parentRef.namespace=="p23a") and .controllerName=="traefik.io/gateway-controller" and any(.conditions[]?; .type=="Accepted" and .status=="True" and .observedGeneration==$generation) and any(.conditions[]?; .type=="ResolvedRefs" and .status=="True" and .observedGeneration==$generation))' && test -z "$(kubectl -n p23a get ingress -o name)" && test "$(curl --fail --silent --show-error --max-time 15 -H 'Host: web.gateway.test' http://10.77.0.11:30080/)" = GATEWAY_OK); do test "$(date +%s)" -lt "$deadline" || exit 1; sleep 2; done
object=$(kubectl -n p23a get gateway entrada -o json) && test -n "$object" && printf '%s\n' "$object" | jq -e '.metadata.generation as $generation | .spec.gatewayClassName=="traefik" and any(.status.conditions[]?; .type=="Accepted" and .status=="True" and .observedGeneration==$generation) and any(.status.conditions[]?; .type=="Programmed" and .status=="True" and .observedGeneration==$generation)' && object=$(kubectl -n p23a get httproute web -o json) && test -n "$object" && printf '%s\n' "$object" | jq -e '.metadata.generation as $generation | (.spec.hostnames|index("web.gateway.test"))!=null and any(.status.parents[]?; .parentRef.name=="entrada" and (.parentRef.namespace==null or .parentRef.namespace=="p23a") and .controllerName=="traefik.io/gateway-controller" and any(.conditions[]?; .type=="Accepted" and .status=="True" and .observedGeneration==$generation) and any(.conditions[]?; .type=="ResolvedRefs" and .status=="True" and .observedGeneration==$generation))' && test -z "$(kubectl -n p23a get ingress -o name)" && test "$(curl --fail --silent --show-error --max-time 15 -H 'Host: web.gateway.test' http://10.77.0.11:30080/)" = GATEWAY_OK
echo EQUIVALENCIA_PARENTREF_EXPLICITA_OK
kubectl -n p23a delete httproute web
sleep 5
kubectl get --raw=/readyz --request-timeout=20s
if (set -eu; object=$(kubectl -n p23a get gateway entrada -o json) && test -n "$object" && printf '%s\n' "$object" | jq -e '.metadata.generation as $generation | .spec.gatewayClassName=="traefik" and any(.status.conditions[]?; .type=="Accepted" and .status=="True" and .observedGeneration==$generation) and any(.status.conditions[]?; .type=="Programmed" and .status=="True" and .observedGeneration==$generation)' && object=$(kubectl -n p23a get httproute web -o json) && test -n "$object" && printf '%s\n' "$object" | jq -e '.metadata.generation as $generation | (.spec.hostnames|index("web.gateway.test"))!=null and any(.status.parents[]?; .parentRef.name=="entrada" and (.parentRef.namespace==null or .parentRef.namespace=="p23a") and .controllerName=="traefik.io/gateway-controller" and any(.conditions[]?; .type=="Accepted" and .status=="True" and .observedGeneration==$generation) and any(.conditions[]?; .type=="ResolvedRefs" and .status=="True" and .observedGeneration==$generation))' && test -z "$(kubectl -n p23a get ingress -o name)" && test "$(curl --fail --silent --show-error --max-time 15 -H 'Host: web.gateway.test' http://10.77.0.11:30080/)" = GATEWAY_OK); then echo ERROR_ACEPTO_INCOMPLETO; exit 1; fi
