echo INICIO_c23-b
kubectl get --raw=/readyz --request-timeout=20s
kubectl wait --for=condition=Ready node/cka-w1 --timeout=120s
test -z "$(kubectl get namespace p23b --ignore-not-found -o name)"
kubectl create namespace p23b
kubectl -n p23b wait --for=create serviceaccount/default --timeout=90s
printf '%s\n' '{"apiVersion":"v1","kind":"Pod","metadata":{"name":"web","namespace":"p23b","labels":{"app":"web"}},"spec":{"terminationGracePeriodSeconds":1,"containers":[{"name":"app","image":"busybox:1.37.0-musl","imagePullPolicy":"Never","command":["sh","-c","mkdir -p /www; printf '\''%s\\n'\'' '\''FRONTEND_OK'\'' >/www/index.html; exec httpd -f -p 8080 -h /www"]}]}}' | kubectl apply -f -
