kubectl -n p23b wait --for=condition=Ready pod/web --timeout=180s
printf '%s\n' '{"apiVersion":"v1","kind":"Pod","metadata":{"name":"api","namespace":"p23b","labels":{"app":"api"}},"spec":{"terminationGracePeriodSeconds":1,"containers":[{"name":"app","image":"busybox:1.37.0-musl","imagePullPolicy":"Never","command":["sh","-c","mkdir -p /www/api; echo API_OK >/www/index.html; echo API_OK >/www/api/index.html; exec httpd -f -p 8080 -h /www"]}]}}' | kubectl apply -f -
printf '%s\n' '{"apiVersion":"v1","kind":"Service","metadata":{"name":"api","namespace":"p23b"},"spec":{"selector":{"app":"api"},"ports":[{"port":80,"targetPort":8080}]}}' | kubectl apply -f -
