printf '%s\n' '{"apiVersion":"networking.k8s.io/v1","kind":"Ingress","metadata":{"name":"antigua","namespace":"p23b"},"spec":{"ingressClassName":"traefik","rules":[{"host":"tienda.gateway.test","http":{"paths":[{"path":"/","pathType":"Prefix","backend":{"service":{"name":"web","port":{"number":80}}}},{"path":"/api","pathType":"Prefix","backend":{"service":{"name":"api","port":{"number":80}}}}]}}]}}' | kubectl apply -f -
kubectl -n p23b get ingress antigua -o yaml
printf '%s\n' '{"apiVersion":"gateway.networking.k8s.io/v1","kind":"Gateway","metadata":{"name":"entrada","namespace":"p23b"},"spec":{"gatewayClassName":"traefik","listeners":[{"name":"http","protocol":"HTTP","port":8000}]}}' | kubectl apply -f -
printf '%s\n' '{"apiVersion":"gateway.networking.k8s.io/v1","kind":"HTTPRoute","metadata":{"name":"web","namespace":"p23b"},"spec":{"parentRefs":[{"name":"entrada"}],"hostnames":["tienda.gateway.test"],"rules":[{"matches":[{"path":{"type":"PathPrefix","value":"/"}}],"backendRefs":[{"name":"web","port":80}]},{"matches":[{"path":{"type":"PathPrefix","value":"/api"}}],"backendRefs":[{"name":"api","port":80}]}]}}' | kubectl apply -f -
kubectl -n p23b delete ingress antigua
deadline=$(($(date +%s)+120)); until (kubectl -n p23b get gateway entrada -o json | jq -e '.metadata.generation as $generation | .spec.gatewayClassName=="traefik" and any(.status.conditions[]?; .type=="Accepted" and .status=="True" and .observedGeneration==$generation) and any(.status.conditions[]?; .type=="Programmed" and .status=="True" and .observedGeneration==$generation)' && kubectl -n p23b get httproute web -o json | jq -e '.metadata.generation as $generation | (.spec.hostnames|index("tienda.gateway.test"))!=null and any(.status.parents[]?; .parentRef.name=="entrada" and (.parentRef.namespace==null or .parentRef.namespace=="p23b") and .controllerName=="traefik.io/gateway-controller" and any(.conditions[]?; .type=="Accepted" and .status=="True" and .observedGeneration==$generation) and any(.conditions[]?; .type=="ResolvedRefs" and .status=="True" and .observedGeneration==$generation))' && test -z "$(kubectl -n p23b get ingress -o name)" && test "$(curl --fail --silent --show-error --max-time 15 -H 'Host: tienda.gateway.test' http://10.77.0.11:30080/)" = FRONTEND_OK && test "$(curl --fail --silent --show-error --max-time 15 -H 'Host: tienda.gateway.test' http://10.77.0.11:30080/api/)" = API_OK); do test "$(date +%s)" -lt "$deadline" || exit 1; sleep 2; done
