echo POSITIVO_c23-b
kubectl -n p23b patch httproute web --type=json -p '[{"op":"replace","path":"/spec/rules/1/backendRefs/0/port","value":8081}]'
sleep 5
kubectl get --raw=/readyz --request-timeout=20s
if (set -eu; object=$(kubectl -n p23b get gateway entrada -o json) && test -n "$object" && printf '%s\n' "$object" | jq -e '.metadata.generation as $generation | .spec.gatewayClassName=="traefik" and any(.status.conditions[]?; .type=="Accepted" and .status=="True" and .observedGeneration==$generation) and any(.status.conditions[]?; .type=="Programmed" and .status=="True" and .observedGeneration==$generation)' && object=$(kubectl -n p23b get httproute web -o json) && test -n "$object" && printf '%s\n' "$object" | jq -e '.metadata.generation as $generation | (.spec.hostnames|index("tienda.gateway.test"))!=null and any(.status.parents[]?; .parentRef.name=="entrada" and (.parentRef.namespace==null or .parentRef.namespace=="p23b") and .controllerName=="traefik.io/gateway-controller" and any(.conditions[]?; .type=="Accepted" and .status=="True" and .observedGeneration==$generation) and any(.conditions[]?; .type=="ResolvedRefs" and .status=="True" and .observedGeneration==$generation))' && test -z "$(kubectl -n p23b get ingress -o name)" && test "$(curl --fail --silent --show-error --max-time 15 -H 'Host: tienda.gateway.test' http://10.77.0.11:30080/)" = FRONTEND_OK && test "$(curl --fail --silent --show-error --max-time 15 -H 'Host: tienda.gateway.test' http://10.77.0.11:30080/api/)" = API_OK); then echo ERROR_ACEPTO_INCOMPLETO; exit 1; fi
echo NEGATIVO_c23-b
kubectl delete namespace p23b --ignore-not-found --wait=true --timeout=120s
fi
