echo POSITIVO_c23-c
kubectl -n p23c delete secret web-tls
sleep 5
kubectl get --raw=/readyz --request-timeout=20s
if (set -eu; object=$(kubectl -n p23c get gateway entrada -o json) && test -n "$object" && printf '%s\n' "$object" | jq -e '.metadata.generation as $generation | .spec.gatewayClassName=="traefik" and any(.status.conditions[]?; .type=="Accepted" and .status=="True" and .observedGeneration==$generation) and any(.status.conditions[]?; .type=="Programmed" and .status=="True" and .observedGeneration==$generation)' && object=$(kubectl -n p23c get httproute web -o json) && test -n "$object" && printf '%s\n' "$object" | jq -e '.metadata.generation as $generation | (.spec.hostnames|index("seguro.gateway.test"))!=null and any(.status.parents[]?; .parentRef.name=="entrada" and (.parentRef.namespace==null or .parentRef.namespace=="p23c") and .controllerName=="traefik.io/gateway-controller" and any(.conditions[]?; .type=="Accepted" and .status=="True" and .observedGeneration==$generation) and any(.conditions[]?; .type=="ResolvedRefs" and .status=="True" and .observedGeneration==$generation))' && test -z "$(kubectl -n p23c get ingress -o name)" && test "$(curl --fail --silent --show-error --max-time 15 --cacert /root/p23c.crt --resolve seguro.gateway.test:30443:10.77.0.11 https://seguro.gateway.test:30443/)" = GATEWAY_TLS_OK); then echo ERROR_ACEPTO_INCOMPLETO; exit 1; fi
